import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"Feature Specifications","description":"Compare AI test automation methods and the latest tools. Learn how to increase QA efficiency with machine learning-based automated testing.","frontmatter":{"title":"Feature Specifications","description":"Compare AI test automation methods and the latest tools. Learn how to increase QA efficiency with machine learning-based automated testing.","head":[["meta",{"name":"keywords","content":"Test Automation, Testing Generative AI, Playwright, Selenium, Real-time Quality Feedback, Zero-downtime Testing, AI-based Test Automation, Continuous Testing, QAOps, TestOps, Codeless, Low-Code, Self-healing Test, Self-healing, AI Test Automation, Codeless Automation, QA Automation, Software Testing, Test Scenario Creation, Codeless Test, Natural Language Test, Test Automation Tool, Test Automation Platform, Test Efficiency, Playwright, Selenium, QAOps, TestOps, Shift-Left Testing, Shift-Right Testing"}],["meta",{"property":"og:title","content":"AI Test Automation | SyncETA"}],["meta",{"property":"og:description","content":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synceta/spec.html"}]],"sort":2000},"headers":[],"relativePath":"en/synceta/spec.md","filePath":"en/synceta/spec.md","lastUpdated":1784598393000}`),a={name:`en/synceta/spec.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="synceta-hardware-and-software-detailed-specifications" tabindex="-1">SyncETA Hardware and Software Detailed Specifications <a class="header-anchor" href="#synceta-hardware-and-software-detailed-specifications" aria-label="Permalink to “SyncETA Hardware and Software Detailed Specifications”">​</a></h1><p>This document details the hardware and software specifications of the SyncETA regression test automation solution. It describes the user&#39;s web browser action recording, test execution, result management, and other ancillary features.</p><h2 id="_1-system-deployment-and-operating-environment" tabindex="-1">1. System Deployment and Operating Environment <a class="header-anchor" href="#_1-system-deployment-and-operating-environment" aria-label="Permalink to “1. System Deployment and Operating Environment”">​</a></h2><ul><li><strong>Deployment Format</strong>: SyncETA can be deployed as a Docker-based installation (On-premise) or as a Cloud SaaS (Software as a Service) format.</li><li><strong>Security Requirements</strong>: Supports executing LLM models on-premise depending on security requirements.</li><li><strong>Test Environment</strong>: Supports testing in real environments by performing scenario recording and execution against the production server rather than the development server.</li></ul><h2 id="_2-system-components-and-detailed-features" tabindex="-1">2. System Components and Detailed Features <a class="header-anchor" href="#_2-system-components-and-detailed-features" aria-label="Permalink to “2. System Components and Detailed Features”">​</a></h2><p>SyncETA largely consists of the following modules:</p><h3 id="_2-1-synceta-recorder-user-action-recording-module" tabindex="-1">2.1 SyncETA Recorder (User Action Recording Module) <a class="header-anchor" href="#_2-1-synceta-recorder-user-action-recording-module" aria-label="Permalink to “2.1 SyncETA Recorder (User Action Recording Module)”">​</a></h3><p><strong>Technology</strong>: Uses Selenium technology. It utilizes a powerful and easy-to-use framework based on Selenium to simplify test creation and maintenance and optimize the web testing process.</p><p><strong>Features</strong>:</p><ul><li>Captures and records the user&#39;s actual browser actions (clicks, inputs, scrolls, page movements, tab information, etc.) in real-time.</li><li>Records detailed events and DOM information such as URL, XPath, Class, ID, and DOM information during recording.</li><li>Recorded actions are automatically generated into scenarios suitable for testing purposes and saved in JSON/YAML-based formats.</li><li>Supports recording scenarios where multiple users interact simultaneously.</li></ul><p><strong>User Interface</strong>:</p><ul><li>Provides a convenient screen to enter the web URL to record, and freely select the web browser and set its size.</li><li>Collects various user events, and test automation can be easily built using an intuitive GUI and keyword-based non-code methods.</li><li>Also provides a script (JavaScript)-based code method.</li><li>Strengthens data verification capabilities by adding additional conditions (AI, Script) to each event.</li><li>Can add success conditions and set failure recovery scripts for each event.</li><li>Provides functions to assign wait times before execution and specify variable names.</li></ul><h3 id="_2-2-test-executor-automated-test-execution-module" tabindex="-1">2.2 Test Executor (Automated Test Execution Module) <a class="header-anchor" href="#_2-2-test-executor-automated-test-execution-module" aria-label="Permalink to “2.2 Test Executor (Automated Test Execution Module)”">​</a></h3><p><strong>Technology</strong>: Interlocks and uses Playwright MCP (Multi-Channel Platform).</p><p><strong>Features</strong>:</p><ul><li>Automatically generated execution scripts are run in an actual browser automation environment.</li><li>Supports parallel test execution in a multi-browser automation environment, enabling rapid results.</li><li>Supports cross-browser compatibility in various browsers such as Chrome, Firefox, and Edge, and the addition of Safari browser has also been requested.</li><li>Provides execution result reports (pass/fail logs, screenshots, etc.), and failed test cases are automatically logged.</li><li>Provides user-friendly error identification and diagnostic features when errors occur during test execution. It displays screenshots of the error point, recorded screens (video) when the error occurred, and user-friendly error messages. Clicking an error on the dashboard shows a video of the recorded screen at the time of the error.</li></ul><h3 id="_2-3-dashboard-management-system" tabindex="-1">2.3 Dashboard/Management System <a class="header-anchor" href="#_2-3-dashboard-management-system" aria-label="Permalink to “2.3 Dashboard/Management System”">​</a></h3><p><strong>Features</strong>: Provides a dashboard for system monitoring such as scenario registration status, execution status, error status, and browser information.</p><p><strong>Report</strong>:</p><ul><li>Provides precise reports and analysis including execution result visualization and test trend analysis, and can provide custom reports tailored to customer requirements.</li><li>Sends reports using mail templates, and while images can be checked on the dashboard, they are not included in the report.</li></ul><p><strong>Scenario Management Feature</strong>:</p><ul><li>Can classify, search, and version-control saved scenarios.</li><li>Supports version control display for data records at the time of recording and modification history.</li><li>Can extract test scenarios according to customer needs.</li><li>Provides convenience in managing execution history through scenario history filtering.</li><li>Optimizes publishing and UI change inspection tasks by automatically processing tests as failed when UI changes are detected.</li></ul><h3 id="_2-4-dataset-management-feature" tabindex="-1">2.4 Dataset Management Feature <a class="header-anchor" href="#_2-4-dataset-management-feature" aria-label="Permalink to “2.4 Dataset Management Feature”">​</a></h3><p><strong>Features</strong>:</p><ul><li>Can input and manage data in a tabular format, supporting the addition, modification, and deletion of variables.</li><li>You can write directly by calling variable values set in the scenario, or automatically generate mockup data using AI and conduct tests with various values. This feature generates test data, which is distinct from AI automatic generation of test cases.</li><li>Applying datasets enables various case tests.</li><li>Verification Data Setting: Verifies data by granting higher accuracy through the setting of unique values for the site (project).</li></ul><h3 id="_2-5-scenario-management-and-execution-options" tabindex="-1">2.5 Scenario Management and Execution Options <a class="header-anchor" href="#_2-5-scenario-management-and-execution-options" aria-label="Permalink to “2.5 Scenario Management and Execution Options”">​</a></h3><ul><li><strong>Record</strong>: The basic unit that records user events and DOM information.</li><li><strong>Scenario</strong>: A core component that implements test scenarios by systematically integrating record information. Enables tracking execution results through accuracy, stability, and real-time status information via automatic and AI-based verification.</li><li><strong>Collection</strong>: A feature that selects multiple scenarios and executes them sequentially, guaranteeing a consistent workflow by flexibly combining various scenarios. If you want to run one scenario on multiple browsers, you can run it as a collection.</li><li><strong>Story</strong>: A feature that freely connects scenarios through a Flow Chart interface and dynamically executes the next scenario based on verification results. Ensures stability and efficiency with visual workflows and automatic verification.</li><li><strong>Dynamic Test Chaining</strong>: Enables flexible testing through sequential scenario execution based on conditions.</li><li><strong>Initialization upon Re-execution</strong>: Provides an environment initialization function when re-executing a test.</li><li><strong>Scenario Severity Setting</strong>: Supports severity management for each scenario.</li><li>**Can be executed in various environments by modifying data, and performance testing can be done in series/parallel.</li></ul><h2 id="_3-system-operation-and-implementation-details" tabindex="-1">3. System Operation and Implementation Details <a class="header-anchor" href="#_3-system-operation-and-implementation-details" aria-label="Permalink to “3. System Operation and Implementation Details”">​</a></h2><ul><li><strong>Real-time Communication</strong>: Enables checking real-time event actions and DOM information through socket communication.</li><li><strong>Screen Verification</strong>: Additional data verification is possible after capturing the screen for each event through AI.</li><li><strong>CI/CD Integration</strong>: Seamlessly integrates with CI/CD pipelines and various external tools/systems like Jenkins, Git, Azure, DevOps, etc. Through this, it can naturally integrate test automation into the existing development/deployment process, improving the efficiency and quality of the entire software development life cycle.</li><li><strong>Security and Authentication Processing</strong>: Includes various security and authentication processing functions such as automatic login processing, cookie and session management functions, HTTP authentication bypass capability, and VPN/Proxy setting support.</li><li><strong>Reusability and Maintenance Ease</strong>: Increases the reuse and maintenance efficiency of test assets through a modular and reusable test structure.</li></ul><h2 id="_4-expected-effects-excluding-effects-on-test-case-generation-and-learning" tabindex="-1">4. Expected Effects (Excluding effects on test case generation and learning) <a class="header-anchor" href="#_4-expected-effects-excluding-effects-on-test-case-generation-and-learning" aria-label="Permalink to “4. Expected Effects (Excluding effects on test case generation and learning)”">​</a></h2><ul><li><strong>Streamline QA Resources</strong>: Repetitive test tasks are automated, increasing QA work efficiency and reducing QA resources by more than 30%.</li><li><strong>Fast Release and Time-to-Market</strong>: Shortens the development cycle through regression test automation and accelerates time-to-market with rapid feedback.</li><li><strong>Test Automation without Writing Code</strong>: Users lacking development knowledge can also easily build test automation with an intuitive GUI and keyword-based non-code methods.</li><li><strong>Provide a Flexible Test Environment</strong>: Supports various execution options and customization such as cross-browser compatibility, parallel execution, and dynamic chaining. Designed to flexibly adjust and expand test environments and functions according to customer needs.</li><li><strong>User-friendly Error Identification</strong>: Facilitates error analysis by providing user-friendly error messages when an error occurs, recording screenshots, and providing recorded screens when an error occurs.</li><li><strong>Increase Accessibility and Efficiency of Test Execution</strong>: By allowing Excel test cases to be executed directly without the existing scenario recording process, QA engineers can flexibly perform tests and save time.</li><li><strong>Improve Test Quality and Reliability</strong>: Prevents human error and maintains consistent quality. Discovers errors early and guarantees continuous and stable quality.</li></ul><hr>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};